import { describe, it, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

// TEST-4 (richer-actions ITEM-4) — the collector projects the new discoverability
// metadata into the committed AI manifest (`frontend-actions.json`), so richer
// names/descriptions reach the agent. Asserts the enrichment is actually present on
// the committed artifact (regenerated by `npm run check`'s collect-actions gate).
//
// STRIP (single-cell): the enriched `dataset.add.byId` entry left with the dataset
// actions; the kept surface's only description-carrying action is
// `mcp.updateSettings` (group "Admin"), and the "lean" contract stays pinned on
// `app.navigate`.

const MANIFEST = fileURLToPath(
  new URL('../../../../server/src/modules/mcp/frontend-actions.json', import.meta.url),
)

interface ManifestAction {
  id: string
  title: string
  group?: string
  description?: string
  aliases?: string[]
}

describe('frontend-actions manifest enrichment (ITEM-4)', () => {
  const manifest = JSON.parse(readFileSync(MANIFEST, 'utf8')) as { actions: ManifestAction[] }

  it('carries description + group for mcp.updateSettings', () => {
    const a = manifest.actions.find(x => x.id === 'mcp.updateSettings')
    expect(a).toBeTruthy()
    expect(a?.description).toMatch(/mcp/i)
    expect(a?.group).toBe('Admin')
  })

  it('leaves a pre-existing action without these fields lean (no empty arrays)', () => {
    // app.navigate never declared aliases/keywords → the collector omits them.
    const a = manifest.actions.find(x => x.id === 'app.navigate')
    expect(a).toBeTruthy()
    expect(a && 'aliases' in a).toBe(false)
    expect(a && 'keywords' in a).toBe(false)
  })
})
